<?php
require_once __DIR__ . '/../includes/db.php'; require_admin(); $errors=[]; $recipientId=(int)($_POST['user_id']??0); $message=trim($_POST['message']??'');
if ($_SERVER['REQUEST_METHOD']==='POST') { if($recipientId<1){$errors[]='Select a recipient.';} if($message===''||strlen($message)>255){$errors[]='Enter a message of up to 255 characters.';} if(!$errors){$user=$pdo->prepare('SELECT user_id FROM users WHERE user_id=?');$user->execute([$recipientId]);if(!$user->fetch()){$errors[]='Recipient not found.';}else{create_notification($pdo,$recipientId,$message,'Admin Message');set_flash('success','Notification sent.');redirect('admin/notifications.php');}} }
$page_title='Send Notification';$users=$pdo->query("SELECT user_id,name,email FROM users WHERE status='Active' ORDER BY name")->fetchAll();require_once __DIR__ . '/../includes/header.php';require __DIR__ . '/_nav.php';
?>
<div class="row"><div class="col-lg-7"><div class="card shadow-sm"><div class="card-body p-4"><h1 class="h4 mb-3">Send Admin Notification</h1><?php if($errors):?><div class="alert alert-danger"><?php foreach($errors as $error):?><div><?php echo e($error); ?></div><?php endforeach;?></div><?php endif;?><form method="post"><div class="mb-3"><label class="form-label required" for="user_id">Recipient</label><select class="form-select" id="user_id" name="user_id" required><option value="">Choose a user</option><?php foreach($users as $user):?><option value="<?php echo e($user['user_id']); ?>" <?php echo $recipientId===$user['user_id']?'selected':''; ?>><?php echo e($user['name'].' ('.$user['email'].')'); ?></option><?php endforeach;?></select></div><div class="mb-4"><label class="form-label required" for="message">Message</label><textarea class="form-control" id="message" name="message" rows="5" maxlength="255" required><?php echo e($message); ?></textarea></div><button class="btn btn-brand">Send Notification</button></form></div></div></div></div><?php require_once __DIR__ . '/../includes/footer.php'; ?>
